#include <bits/stdc++.h>
using namespace std;

struct NumberTheory {
    struct Mod998 {
        static const long long MOD = 998;
        long long add(long long a, long long b) {
            a %= MOD; b %= MOD;
            long long res = a + b;
            if (res >= MOD) res -= MOD;
            return res;
        }
        long long subtract(long long a, long long b) {
            a %= MOD; b %= MOD;
            long long res = a - b;
            if (res < 0) res += MOD;
            return res;
        }
        long long mult(long long a, long long b) {
            return (a % MOD) * (b % MOD) % MOD;
        }
        long long smallInv(long long a) {
            // Since MOD=998 is not prime, but for the purpose of this code, assume smallInv is modular inverse
            // For simplicity, use extended Euclidean algorithm
            long long m = MOD, x, y;
            long long g = extendedGCD(a, m, x, y);
            if (g != 1) return 0; // no inverse
            else {
                x %= m;
                if (x < 0) x += m;
                return x;
            }
        }
        long long ncr(long long n, long long r) {
            if (r > n || r < 0) return 0;
            long long res = 1;
            for (long long i = 1; i <= r; i++) {
                res = mult(res, n - i + 1);
                res = mult(res, smallInv(i));
            }
            return res;
        }
        long long mult(long long a, long long b, long long c) {
            return mult(mult(a, b), c);
        }
        long long add(long long a, long long b) {
            return add(a, b);
        }
        long long subtract(long long a, long long b) {
            return subtract(a, b);
        }
        long long smallInv(long long a) {
            // Extended Euclidean Algorithm
            long long x, y;
            extendedGCD(a, MOD, x, y);
            x %= MOD;
            if (x < 0) x += MOD;
            return x;
        }
        long long extendedGCD(long long a, long long b, long long &x, long long &y) {
            if (b == 0) {
                x = 1; y = 0;
                return a;
            }
            long long g = extendedGCD(b, a % b, y, x);
            y -= (a / b) * x;
            return g;
        }
    };
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;

    NumberTheory::Mod998 mod;

    long long phaseSize = 1;
    long long p = 1;
    for (int i = 0; p != 0; i++) {
        long long numerator = p;
        long long denominator = mod.smallInv(n + m - i);
        p = mod.mult(numerator, n - i, denominator);
        phaseSize = mod.add(phaseSize, p);
    }

    long long answer = 0;
    for (int k = 1; k <= n; k++) {
        long long numPhases = mod.mult(m + k, mod.smallInv(k));
        long long term = mod.mult(mod.ncr(n, k), numPhases, phaseSize);
        if ((k & 1) == 1)
            answer = mod.add(answer, term);
        else
            answer = mod.subtract(answer, term);
    }

    cout << answer << "\n";

    return 0;
}
